        userId: String,
        password: CharArray,
        sourceUri: Uri,
        metadataUri: Uri
    ) {
        _isLoading.value = true
        viewModelScope.launch {
            val result = restoreUseCase(userId, password, sourceUri, metadataUri)
            _restoreResult.postValue(result)
            _isLoading.postValue(false)
        }
    }
}
