        } else {
            articleRepository.saveForOffline(article.id)
        }
    }

    fun getSavedArticles(): Flow<List<Article>> {
        return articleRepository.getSavedArticles()
    }

    fun getSavedCount(): Flow<Int> {
        return articleRepository.getSavedCount()
    }
}
"}

