            jobRunRepository.getBySourceRule(sourceRuleId, limit, offset)
        } else {
            jobRunRepository.getAll(limit, offset)
        }
    }

    fun getBatchQualityHistory(
        limit: Int = 50,
        offset: Int = 0,
        userRole: UserRole
    ): Flow<List<DataBatchVersion>> {
        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR, UserRole.ANALYST))
        return batchValidationRepository.getRecentBatches(limit, offset)
    }

    fun getFailedBatches(userRole: UserRole): Flow<List<DataBatchVersion>> {
        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR, UserRole.ANALYST))
        return batchValidationRepository.getFailedBatches()
    }

    fun getValidationErrors(batchVersionId: String, userRole: UserRole): Flow<List<ValidationError>> {
        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR, UserRole.ANALYST))
        return batchValidationRepository.getErrorsForBatch(batchVersionId)
    }

    fun getPendingArticles(limit: Int = 50, offset: Int = 0, userRole: UserRole): Flow<List<Article>> {
        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
        return articleRepository.getByCurationStatus(CurationStatus.PENDING_REVIEW, limit, offset)
    }

    fun getPendingReviewCount(userRole: UserRole): Flow<Int> {
        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
        return articleRepository.getPendingReviewCount()
    }
}
